#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_render_root_candidate.h"
#include <iostream>
int main(){try{auto graph=loadGraph("work/roundtrip-11.dmx");if(sessionRenderRootCandidate(graph)!=2237)throw std::runtime_error("saved root coverage");std::swap(graph.elements.at(100),graph.elements.at(2237));for(auto&element:graph.elements)for(auto&attribute:element.attributes)for(auto&value:attribute.values){if(value.reference==100)value.reference=2237;else if(value.reference==2237)value.reference=100;}if(sessionRenderRootCandidate(graph)!=100||sessionRenderRootCandidate(graph,100)!=100)throw std::runtime_error("relocated root selection");saveGraph(graph,"work/relocated-root-session.dmx");auto loaded=loadGraph("work/relocated-root-session.dmx");if(sessionRenderRootCandidate(loaded)!=100)throw std::runtime_error("root fixture roundtrip");auto&attributes=graph.elements.front().attributes;size_t index=0;for(;index<attributes.size();++index)if(graph.strings.at(attributes[index].name)=="activeClip")break;if(index==attributes.size())throw std::runtime_error("active clip test schema");auto saved=attributes[index];attributes[index].values[0].reference=UINT32_MAX;bool invalid=false;try{sessionRenderRootCandidate(graph);}catch(const std::runtime_error&){invalid=true;}if(!invalid||sessionRenderRootCandidate(graph,100)!=100)throw std::runtime_error("invalid reference / explicit override");attributes[index]=saved;attributes.push_back(saved);bool duplicate=false;try{sessionRenderRootCandidate(graph);}catch(const std::runtime_error&){duplicate=true;}if(!duplicate)throw std::runtime_error("ambiguous active clip accepted");bool wrong=false;try{sessionRenderRootCandidate(loaded,UINT32_MAX);}catch(const std::runtime_error&){wrong=true;}if(!wrong)throw std::runtime_error("invalid explicit root accepted");std::cout<<"session render root passed saved_activeClip=2237 relocated_activeClip=100 explicit_root=validated malformed_references=rejected duplicate_activeClip=rejected\n";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
